-- =====================================================================
-- Scheduled 4 of 4 · Check past scores against what actually happened
-- Schedule: weekly, e.g. Monday 08:00
-- Generated by `python -m appchurn.bqml`; edit config.py, not this file.
--
-- Scores need 14 days before their outcome is known. For every score
-- date in the last four weeks whose outcome is now complete:
-- a) Records whether each scored user came back (same rule as training).
-- b) Writes ROC-AUC against the recency rule, predicted vs actual churn,
--    High-band churn, and contacted vs holdout churn to model_monitoring,
--    with a status: alert if the model no longer beats the rule or is off
--    by more than 10 points, warning above 5 points.
--
-- Input drift and event-tracking checks run in Python (appchurn.monitor).
-- =====================================================================

DECLARE run_date DATE DEFAULT DATE '2018-10-04';  -- when scheduling, use: DEFAULT @run_date
DECLARE latest_complete DATE;
DECLARE earliest DATE;

SET latest_complete = DATE_SUB(run_date, INTERVAL 14 DAY);  -- outcome complete by yesterday
SET earliest = DATE_SUB(latest_complete, INTERVAL 27 DAY);  -- re-check the last four weeks

-- a) Outcomes of past scores
EXECUTE IMMEDIATE REPLACE(REPLACE(REPLACE(REPLACE(r"""
CREATE OR REPLACE TABLE `your-project-id.churn_demo.score_outcomes` AS
WITH activity AS (
  SELECT DISTINCT user_pseudo_id, PARSE_DATE('%Y%m%d', event_date) AS activity_date
  FROM `firebase-public-project.analytics_153293282.events_*`
  WHERE _TABLE_SUFFIX BETWEEN '__FIRST_SUFFIX__' AND '__LAST_SUFFIX__'
    AND event_name NOT IN ('app_remove', 'app_update', 'app_clear_data', 'os_update', 'app_exception', 'notification_receive', 'notification_dismiss', 'firebase_campaign', 'dynamic_link_app_update')
)
SELECT
  a.score_date,
  a.user_pseudo_id,
  a.model_name,
  a.churn_probability,
  a.risk_band,
  a.in_holdout,
  a.days_since_last_active,
  a.active_days_28d,
  IF(COUNT(act.activity_date) = 0, 1, 0) AS churned
FROM `your-project-id.churn_demo.at_risk_customers` AS a
LEFT JOIN activity AS act
  ON act.user_pseudo_id = a.user_pseudo_id
 AND act.activity_date >= a.score_date
 AND act.activity_date < DATE_ADD(a.score_date, INTERVAL 14 DAY)
WHERE a.score_date BETWEEN DATE '__EARLIEST__' AND DATE '__LATEST__'
GROUP BY 1, 2, 3, 4, 5, 6, 7, 8
""",
  '__FIRST_SUFFIX__', FORMAT_DATE('%Y%m%d', earliest)),
  '__LAST_SUFFIX__', FORMAT_DATE('%Y%m%d', DATE_SUB(run_date, INTERVAL 1 DAY))),
  '__EARLIEST__', CAST(earliest AS STRING)),
  '__LATEST__', CAST(latest_complete AS STRING));

-- b) Metrics per score date; replace this window's rows
DELETE FROM `your-project-id.churn_demo.model_monitoring` WHERE score_date BETWEEN earliest AND latest_complete;
INSERT INTO `your-project-id.churn_demo.model_monitoring`
WITH base AS (
  SELECT *, days_since_last_active - 0.01 * active_days_28d AS rule_score
  FROM `your-project-id.churn_demo.score_outcomes`
),
ranked AS (
  SELECT
    *,
    RANK() OVER (PARTITION BY score_date ORDER BY churn_probability) + (COUNT(*) OVER (PARTITION BY score_date, churn_probability) - 1) / 2 AS r_model,
    RANK() OVER (PARTITION BY score_date ORDER BY rule_score) + (COUNT(*) OVER (PARTITION BY score_date, rule_score) - 1) / 2 AS r_rule
  FROM base
),
per_day AS (
  SELECT
    score_date,
    ANY_VALUE(model_name) AS model_name,
    COUNT(*) AS users,
    AVG(churn_probability) AS mean_predicted,
    AVG(churned) AS actual_churn,
    (SUM(IF(churned = 1, r_model, 0)) - COUNTIF(churned = 1) * (COUNTIF(churned = 1) + 1) / 2) / NULLIF(COUNTIF(churned = 1) * COUNTIF(churned = 0), 0) AS roc_auc,
    (SUM(IF(churned = 1, r_rule, 0)) - COUNTIF(churned = 1) * (COUNTIF(churned = 1) + 1) / 2) / NULLIF(COUNTIF(churned = 1) * COUNTIF(churned = 0), 0) AS rule_roc_auc,
    AVG(IF(risk_band = 'High', churned, NULL)) AS high_band_churn,
    AVG(IF(risk_band IN ('High', 'Medium') AND NOT in_holdout, churned, NULL)) AS contacted_churn,
    AVG(IF(risk_band IN ('High', 'Medium') AND in_holdout, churned, NULL)) AS holdout_churn,
    COUNTIF(risk_band IN ('High', 'Medium') AND in_holdout) AS holdout_users
  FROM ranked
  GROUP BY score_date
)
SELECT
  *,
  CASE
    WHEN roc_auc <= rule_roc_auc OR ABS(mean_predicted - actual_churn) > 0.10 THEN 'alert'
    WHEN ABS(mean_predicted - actual_churn) > 0.05 THEN 'warning'
    ELSE 'ok'
  END AS status,
  CURRENT_TIMESTAMP() AS checked_at
FROM per_day;

SELECT * FROM `your-project-id.churn_demo.model_monitoring` ORDER BY score_date DESC LIMIT 10;
